import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, w;

        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        @Override
        public int compareTo(Edge o) {
            return Integer.compare(this.w, o.w);
        }
    }

    static int[] parentDSU;

    static int find(int i) {
        if (parentDSU[i] == i)
            return i;
        return parentDSU[i] = find(parentDSU[i]);
    }

    static int[] leftChild, rightChild, nodeWeight;
    static long[] nodeSum;
    static long[] ans;

    static void dfs(int u, long currentVal) {
        if (leftChild[u] == 0 && rightChild[u] == 0) {
            ans[u] = currentVal;
            return;
        }

        int l = leftChild[u];
        int r = rightChild[u];
        int w = nodeWeight[u];

        if (l != 0) {
            if (nodeSum[l] >= w) {
                dfs(l, currentVal);
            } else {
                dfs(l, nodeSum[l]);
            }
        }

        if (r != 0) {
            if (nodeSum[r] >= w) {
                dfs(r, currentVal);
            } else {
                dfs(r, nodeSum[r]);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        int totalCells = n * m;

        int[] P = new int[totalCells + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = i * m + j + 1;
                P[id] = in.nextInt();
            }
        }

        if (totalCells == 1) {
            out.print(P[1]);
            out.println();
            out.flush();
            return;
        }

        int maxEdges = 2 * totalCells;
        Edge[] edges = new Edge[maxEdges];
        int edgeCount = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int u = i * m + j + 1;
                if (i + 1 < n) {
                    int v = (i + 1) * m + j + 1;
                    edges[edgeCount++] = new Edge(u, v, Math.max(P[u], P[v]));
                }
                if (j + 1 < m) {
                    int v = i * m + (j + 1) + 1;
                    edges[edgeCount++] = new Edge(u, v, Math.max(P[u], P[v]));
                }
            }
        }

        edges = Arrays.copyOf(edges, edgeCount);
        Arrays.sort(edges);

        int maxNodes = 2 * totalCells;
        parentDSU = new int[maxNodes + 1];
        for (int i = 1; i <= maxNodes; i++) {
            parentDSU[i] = i;
        }

        leftChild = new int[maxNodes + 1];
        rightChild = new int[maxNodes + 1];
        nodeWeight = new int[maxNodes + 1];
        nodeSum = new long[maxNodes + 1];
        ans = new long[totalCells + 1];

        for (int i = 1; i <= totalCells; i++) {
            nodeSum[i] = P[i];
        }

        int currNode = totalCells;
        for (int i = 0; i < edgeCount; i++) {
            int rootU = find(edges[i].u);
            int rootV = find(edges[i].v);

            if (rootU != rootV) {
                currNode++;
                leftChild[currNode] = rootU;
                rightChild[currNode] = rootV;
                nodeWeight[currNode] = edges[i].w;
                nodeSum[currNode] = nodeSum[rootU] + nodeSum[rootV];

                parentDSU[rootU] = currNode;
                parentDSU[rootV] = currNode;
            }
        }

        dfs(currNode, nodeSum[currNode]);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int id = i * m + j + 1;
                out.print(ans[id]);
                if (j + 1 < m) {
                    out.print(' ');
                }
            }
            out.println();
        }

        out.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') {
                    throw new IOException("Caractere inesperado");
                }
                res = res * 10 + c - '0';
                c = read();
            }
            return res;
        }
    }

    static class FastOutput {
        private final OutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;

        public FastOutput(OutputStream out) {
            this.out = out;
        }

        private void write(byte b) throws IOException {
            if (head >= buffer.length) {
                flush();
            }
            buffer[head++] = b;
        }

        public void print(char c) throws IOException {
            write((byte) c);
        }

        public void print(long val) throws IOException {
            if (val == 0) {
                write((byte) '0');
                return;
            }
            if (val < 0) {
                write((byte) '-');
                val = -val;
            }
            byte[] digits = new byte[20];
            int len = 0;
            while (val > 0) {
                digits[len++] = (byte) ('0' + (val % 10));
                val /= 10;
            }
            while (len > 0) {
                write(digits[--len]);
            }
        }

        public void println() throws IOException {
            write((byte) '\n');
        }

        public void flush() throws IOException {
            if (head > 0) {
                out.write(buffer, 0, head);
                head = 0;
            }
        }
    }
}
